// Host C11 ABI witness ONLY for x86_64 Linux System V.
// This is hand-authored test code, not generated by an AttoLang compiler.
// Other targets must have separately built target-specific header witnesses.
#include <stdint.h>
#include <stddef.h>
#include <stdalign.h>
#include <stdio.h>

#if !defined(__linux__) || !defined(__x86_64__) || !defined(__BYTE_ORDER__) || !defined(__ORDER_LITTLE_ENDIAN__)
#error "E_ABI_TARGET_UNKNOWN: this C11 witness is only for little-endian Linux x86_64"
#elif __BYTE_ORDER__ != __ORDER_LITTLE_ENDIAN__
#error "E_ABI_TARGET_UNKNOWN: this witness requires little-endian"
#endif

typedef struct SamplePacket {
  uint8_t tag;
  int64_t counter;
  uint32_t flags;
} SamplePacket;

_Static_assert(sizeof(uint8_t) == 1, "u8 width");
_Static_assert(sizeof(int64_t) == 8, "i64 width");
_Static_assert(sizeof(uint32_t) == 4, "u32 width");
_Static_assert(sizeof(SamplePacket) == 24, "E_ABI_LAYOUT_MISMATCH: sizeof");
_Static_assert(alignof(SamplePacket) == 8, "E_ABI_LAYOUT_MISMATCH: alignof");
_Static_assert(offsetof(SamplePacket, tag) == 0, "E_ABI_LAYOUT_MISMATCH: tag");
_Static_assert(offsetof(SamplePacket, counter) == 8, "E_ABI_LAYOUT_MISMATCH: counter");
_Static_assert(offsetof(SamplePacket, flags) == 16, "E_ABI_LAYOUT_MISMATCH: flags");

int main(void) {
  printf("sample-packet-c11-x86_64: sizeof=%zu align=%zu offsets=%zu,%zu,%zu\n",
      sizeof(SamplePacket), alignof(SamplePacket), offsetof(SamplePacket, tag),
      offsetof(SamplePacket, counter), offsetof(SamplePacket, flags));
  return 0;
}
